import{_ as a,o as n,c as e,ae as s}from"./chunks/framework.DJK_dC0-.js";const u=JSON.parse('{"title":"Python 后端基础：从函数到可交付服务","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/backend-foundation.md","filePath":"tutorial/backend-foundation.md"}'),d={name:"tutorial/backend-foundation.md"};function i(o,t,r,p,l,c){return n(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="python-后端基础-从函数到可交付服务" tabindex="-1">Python 后端基础：从函数到可交付服务 <a class="header-anchor" href="#python-后端基础-从函数到可交付服务" aria-label="Permalink to &quot;Python 后端基础：从函数到可交付服务&quot;">​</a></h1><p>本章只保留 Agent 岗位和后端交付会用到的 Python 能力。</p><h2 id="能力链" tabindex="-1">能力链 <a class="header-anchor" href="#能力链" aria-label="Permalink to &quot;能力链&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数据模型</span></span>
<span class="line"><span>→ 输入校验</span></span>
<span class="line"><span>→ 业务函数</span></span>
<span class="line"><span>→ 异步边界</span></span>
<span class="line"><span>→ HTTP API</span></span>
<span class="line"><span>→ 持久化适配器</span></span>
<span class="line"><span>→ 测试与可观测性</span></span>
<span class="line"><span>→ Docker/CI</span></span></code></pre></div><p>每一层都必须能独立测试。先用标准库 fixture 理解机制，再接入 FastAPI、Pydantic、数据库和真实模型服务。</p><h2 id="js-ts-到-python-的迁移重点" tabindex="-1">JS/TS 到 Python 的迁移重点 <a class="header-anchor" href="#js-ts-到-python-的迁移重点" aria-label="Permalink to &quot;JS/TS 到 Python 的迁移重点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>已有经验</th><th>Python 目标能力</th><th>关键差异</th></tr></thead><tbody><tr><td>TypeScript interface</td><td>dataclass / Pydantic model</td><td>注解不会自动做运行时校验</td></tr><tr><td>Promise</td><td>coroutine / TaskGroup</td><td>取消、超时和阻塞调用必须明确</td></tr><tr><td>Express middleware</td><td>FastAPI dependency</td><td>依赖解析和请求生命周期可测试</td></tr><tr><td>Jest/Vitest</td><td>pytest</td><td>fixture、参数化和退出码进入交付门禁</td></tr><tr><td>JSON API</td><td>typed request/response</td><td>错误 code、trace id 和版本必须稳定</td></tr><tr><td>state machine</td><td>checkpoint / recovery</td><td>重试前先读取外部状态</td></tr></tbody></table><h2 id="通过标准" tabindex="-1">通过标准 <a class="header-anchor" href="#通过标准" aria-label="Permalink to &quot;通过标准&quot;">​</a></h2><ul><li>能从新起点写出一个带输入校验的 API；</li><li>能覆盖成功、非法输入、超时、重复请求和依赖失败；</li><li>能解释哪些调用可重试，哪些副作用必须人工确认；</li><li>能写出一份运行命令、依赖版本、故障处理和选型说明；</li><li>能把同一接口迁移到新的存储适配器而不改变调用方契约。</li></ul><p>浏览器中的 Pyodide 只能证明纯 Python 练习。涉及网络、数据库、进程、FastAPI 或 Docker 的任务必须在隔离沙箱或本机运行。</p>`,10)])])}const P=a(d,[["render",i]]);export{u as __pageData,P as default};
